import glob

totals = {}
for path in glob.glob("sales/*.csv"):
    with open(path, encoding="utf-8") as f:
        next(f)
        for line in f:
            dish, qty = line.strip().split(",")
            totals[dish] = totals.get(dish, 0) + int(qty)
for dish in sorted(totals):
    print(dish, totals[dish])
